1	"use server";
2	
3	/**
4	 * Free Minecraft servers — one per verified account, running as a Docker
5	 * container on the dedicated "freemc-host" VM behind itzg/mc-router (hostname
6	 * -based routing + auto-scale up/down on connect/idle — see FreeMinecraftServer
7	 * in prisma/schema.prisma for the full architecture note).
8	 *
9	 * KNOWN GAP: disk usage is NOT hard-quota-enforced yet (Docker's storage-opt
10	 * quota needs XFS+pquota, which this host's filesystem doesn't have). The RAM
11	 * cap (Docker --memory, a real hard ceiling) and the total-server-count cap are
12	 * the enforced safety controls for now; `free_minecraft_disk_mb` exists for a
13	 * future periodic `du`-based sweep, not wired to anything yet.
14	 */
15	import { revalidatePath } from "next/cache";
16	import { db } from "./db";
17	import { requireUser } from "./auth";
18	import { assertEmailVerified } from "./email-verification";
19	import { checkRateLimit } from "./rate-limit";
20	import { getSettingBool, getSettingInt, getSetting } from "./settings";
21	import { withServerSsh, exec, shellQuote } from "./ssh-exec";
22	import type { SftpServer } from "./sftp";
23	import { validateRconCommand } from "./game-control";
24	import { schemaFor, validateConfig } from "./game-config";
25	import {
26	  rconPasswordFor,
27	  getFreeServerStatus,
28	  getFreeServerPlayers,
29	  sendRcon,
30	  readServerProperties,
31	  writeServerProperties,
32	  liveRconCommandFor,
33	  propertiesToEnv,
34	  FREEMC_PRESETS,
35	  FREEMC_PLUGIN_MC_VERSION,
36	} from "./free-minecraft-control";
37	
38	type Result = { error?: string };
39	
40	const SUBDOMAIN_RE = /^[a-z0-9]([a-z0-9-]{1,18}[a-z0-9])?$/;
41	const RESERVED = new Set(["www", "api", "admin", "mc", "play", "test", "server", "router"]);
42	
43	/** The dedicated Docker host — a real Server row (Server.hostname="freemc-host"),
44	 *  not a customer VPS. Reused via the same withServerSsh every game/backup
45	 *  action already uses; this just points it at our own internal box instead. */
46	async function freemcHost(): Promise<SftpServer> {
47	  const host = await db.server.findFirst({
48	    where: { hostname: "freemc-host" },
49	    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
50	  });
51	  if (!host) throw new Error("Free Minecraft host is not provisioned.");
52	  return host;
53	}
54	
55	export async function getMyFreeMinecraftServer() {
56	  const user = await requireUser();
57	  return db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
58	}
59	
60	export async function createFreeMinecraftServer(_prev: unknown, formData: FormData): Promise<Result> {
61	  const user = await requireUser();
62	  const subdomain = String(formData.get("subdomain") ?? "");
63	  const presetKey = String(formData.get("preset") ?? "vanilla");
64	  const preset = FREEMC_PRESETS[presetKey] ?? FREEMC_PRESETS.vanilla;
65	
66	  if (!(await getSettingBool("free_minecraft_enabled", false))) {
67	    return { error: "Free Minecraft servers aren't open yet — check back soon." };
68	  }
69	
70	  try {
71	    await assertEmailVerified(user);
72	  } catch {
73	    return { error: "Verify your email first — check your inbox for the link." };
74	  }
75	
76	  const rl = checkRateLimit(`freemc:create:${user.id}`, { max: 5, windowMs: 60_000 });
77	  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };
78	
79	  const sub = subdomain.trim().toLowerCase();
80	  if (!SUBDOMAIN_RE.test(sub) || RESERVED.has(sub)) {
81	    return { error: "Pick a name: 3-20 lowercase letters, numbers, or hyphens, not a reserved word." };
82	  }
83	
84	  const existing = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
85	  if (existing) return { error: "You already have a free server. Delete it before creating another." };
86	
87	  const maxTotal = await getSettingInt("free_minecraft_max_concurrent", 8);
88	  const total = await db.freeMinecraftServer.count({ where: { status: { not: "DELETED" } } });
89	  if (total >= maxTotal) {
90	    return { error: "Free servers are at capacity right now — please try again later." };
91	  }
92	
93	  const domain = await getSetting("free_minecraft_domain", "play.nxeon.cloud");
94	  const ramMb = await getSettingInt("free_minecraft_ram_mb", 1024);
95	
96	  // Derived from userId (unique, known up front) rather than the row's own id,
97	  // so creation is a single write — no awkward "create with a placeholder,
98	  // then patch in the real name" two-phase step that could race.
99	  const containerName = `mc-free-${user.id}`;
100	  let row;
101	  try {
102	    row = await db.freeMinecraftServer.create({
103	      data: { userId: user.id, subdomain: sub, containerName, status: "CREATING", preset: presetKey in FREEMC_PRESETS ? presetKey : "vanilla" },
104	    });
105	  } catch {
106	    return { error: "That name is taken — try another." };
107	  }
108	
109	  try {
110	    const host = await freemcHost();
111	    const outcome = await withServerSsh(host, async (conn) => {
112	      const setup = await exec(conn, `mkdir -p ${shellQuote(`/opt/freemc/servers/${row.id}`)}`, 15_000);
113	      if (setup.code !== 0) return { ok: false as const, error: setup.stderr || "mkdir failed" };
114	      return recreatePresetContainer(conn, row, FREEMC_PRESETS.vanilla, user.id, domain, ramMb);
115	    });
116	    if (!outcome.ok) throw new Error(outcome.error);
117	  } catch (e) {
118	    await db.freeMinecraftServer.delete({ where: { id: row.id } }).catch(() => {});
119	    console.error("[free-minecraft] create failed:", e);
120	    return { error: "Couldn't start your server — please try again in a moment." };
121	  }
122	
123	  await db.freeMinecraftServer.update({ where: { id: row.id }, data: { status: "READY" } });
124	  revalidatePath("/dashboard/free-minecraft");
125	  return {};
126	}
127	
128	export async function deleteFreeMinecraftServer(_prev: unknown, _formData: FormData): Promise<Result> {
129	  const user = await requireUser();
130	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
131	  if (!row) return { error: "You don't have a free server." };
132	
133	  try {
134	    const host = await freemcHost();
135	    await withServerSsh(host, async (conn) => {
136	      await exec(conn, `docker rm -f ${shellQuote(row.containerName)}`, 30_000);
137	      await exec(conn, `rm -rf ${shellQuote(`/opt/freemc/servers/${row.id}`)}`, 15_000);
138	    });
139	  } catch (e) {
140	    console.error("[free-minecraft] delete cleanup failed (row is removed regardless):", e);
141	  }
142	
143	  await db.freeMinecraftServer.delete({ where: { id: row.id } });
144	  revalidatePath("/dashboard/free-minecraft");
145	  return {};
146	}
147	
148	/** Fetch the caller's server plus its live Docker/RCON status in one round
149	 *  trip. Returns null fields (not an error) when the server is asleep — that's
150	 *  the normal, common state for a free server nobody's playing on right now. */
151	export async function getFreeMinecraftDashboard() {
152	  const user = await requireUser();
153	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
154	  if (!row) return null;
155	
156	  let running = false;
157	  let players: { online: number; max: number } | null = null;
158	  try {
159	    const host = await freemcHost();
160	    const status = await withServerSsh(host, (conn) => getFreeServerStatus(conn, row.containerName));
161	    running = status.running;
162	    players = status.players;
163	  } catch (e) {
164	    console.error("[free-minecraft] status check failed:", e);
165	  }
166	
167	  return { ...row, running, players };
168	}
169	
170	/** Power controls. mc-router already starts/stops on connect/idle
171	 *  automatically — these are the manual overrides (force a restart to apply a
172	 *  settings change now, or stop it to free the slot without waiting it out). */
173	export async function startFreeMinecraftServer(_prev: unknown, _formData: FormData): Promise<Result> {
174	  return powerAction("start");
175	}
176	export async function stopFreeMinecraftServer(_prev: unknown, _formData: FormData): Promise<Result> {
177	  return powerAction("stop");
178	}
179	export async function restartFreeMinecraftServer(_prev: unknown, _formData: FormData): Promise<Result> {
180	  return powerAction("restart");
181	}
182	
183	async function powerAction(action: "start" | "stop" | "restart"): Promise<Result> {
184	  const user = await requireUser();
185	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
186	  if (!row) return { error: "You don't have a free server." };
187	
188	  const rl = checkRateLimit(`freemc:power:${user.id}`, { max: 10, windowMs: 60_000 });
189	  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };
190	
191	  try {
192	    const host = await freemcHost();
193	    await withServerSsh(host, async (conn) => {
194	      const r = await exec(conn, `docker ${action} ${shellQuote(row.containerName)}`, 30_000);
195	      if (r.code !== 0) throw new Error(r.stderr || `docker ${action} failed`);
196	    });
197	  } catch (e) {
198	    console.error(`[free-minecraft] ${action} failed:`, e);
199	    return { error: "That didn't work — please try again in a moment." };
200	  }
201	  revalidatePath("/dashboard/free-minecraft");
202	  return {};
203	}
204	
205	export async function renameFreeMinecraftServer(_prev: unknown, formData: FormData): Promise<Result> {
206	  const user = await requireUser();
207	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
208	  if (!row) return { error: "You don't have a free server." };
209	
210	  const name = String(formData.get("name") ?? "").trim().slice(0, 40);
211	  if (!name) return { error: "Enter a name." };
212	
213	  // Cosmetic only — never touches the container, the subdomain, or mc-router.
214	  await db.freeMinecraftServer.update({ where: { id: row.id }, data: { name } });
215	  revalidatePath("/dashboard/free-minecraft");
216	  return {};
217	}
218	
219	/**
220	 * Changes the connect address. The container's own identity (containerName,
221	 * data volume) never changes — only its `mc-router.host` label does, and
222	 * labels are immutable on a running container, so this is a stop -> remove ->
223	 * recreate with the SAME name and data mount, just a new label. World data is
224	 * untouched throughout; there's a few seconds of downtime while it recreates.
225	 */
226	export async function changeFreeMinecraftSubdomain(_prev: unknown, formData: FormData): Promise<Result> {
227	  const user = await requireUser();
228	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
229	  if (!row) return { error: "You don't have a free server." };
230	
231	  const rl = checkRateLimit(`freemc:subdomain:${user.id}`, { max: 5, windowMs: 300_000 });
232	  if (!rl.ok) return { error: `Too many attempts — try again in ${Math.ceil(rl.retryAfterSec / 60)}m.` };
233	
234	  const sub = String(formData.get("subdomain") ?? "").trim().toLowerCase();
235	  if (!SUBDOMAIN_RE.test(sub) || RESERVED.has(sub)) {
236	    return { error: "Pick a name: 3-20 lowercase letters, numbers, or hyphens, not a reserved word." };
237	  }
238	  if (sub === row.subdomain) return {};
239	
240	  const domain = await getSetting("free_minecraft_domain", "play.nxeon.cloud");
241	  const ramMb = await getSettingInt("free_minecraft_ram_mb", 1024);
242	  // Preserve whatever preset was active — moving your connect address
243	  // shouldn't reset your game mode/plugins.
244	  const preset = FREEMC_PRESETS[row.preset] ?? FREEMC_PRESETS.vanilla;
245	
246	  try {
247	    await db.freeMinecraftServer.update({ where: { id: row.id }, data: { subdomain: sub } });
248	  } catch {
249	    return { error: "That name is taken — try another." };
250	  }
251	
252	  try {
253	    const host = await freemcHost();
254	    // "moved": now running under the new subdomain. "reverted": the new
255	    // address failed to boot, so it's back under the OLD one — the DB's
256	    // subdomain field must match, or the dashboard would show a "connect at"
257	    // address nothing is actually listening on.
258	    const outcome = await withServerSsh(host, async (conn) => {
259	      const applied = await recreatePresetContainer(conn, { ...row, subdomain: sub }, preset, user.id, domain, ramMb);
260	      if (applied.ok) return { landed: "moved" as const };
261	      console.error("[free-minecraft] subdomain recreate failed, rolling back:", applied.error);
262	      const rolledBack = await recreatePresetContainer(conn, row, preset, user.id, domain, ramMb);
263	      return rolledBack.ok
264	        ? { landed: "reverted" as const }
265	        : { landed: "broken" as const, error: rolledBack.error };
266	    });
267	
268	    if (outcome.landed !== "moved") {
269	      await db.freeMinecraftServer.update({ where: { id: row.id }, data: { subdomain: row.subdomain } }).catch(() => {});
270	    }
271	    if (outcome.landed === "broken") throw new Error(outcome.error);
272	    if (outcome.landed === "reverted") {
273	      return { error: "That address didn't work — your server is back on its previous one." };
274	    }
275	  } catch (e) {
276	    console.error("[free-minecraft] subdomain change failed:", e);
277	    return { error: "Couldn't move your server to the new address — please try again." };
278	  }
279	  revalidatePath("/dashboard/free-minecraft");
280	  return {};
281	}
282	
283	export async function sendFreeMinecraftCommand(_prev: unknown, formData: FormData): Promise<{ error?: string; response?: string }> {
284	  const user = await requireUser();
285	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
286	  if (!row) return { error: "You don't have a free server." };
287	
288	  const rl = checkRateLimit(`freemc:rcon:${user.id}`, { max: 20, windowMs: 60_000 });
289	  if (!rl.ok) return { error: `Too many commands — try again in ${rl.retryAfterSec}s.` };
290	
291	  const parsed = validateRconCommand(String(formData.get("command") ?? ""));
292	  if (!parsed.ok) return { error: parsed.error };
293	
294	  try {
295	    const host = await freemcHost();
296	    const result = await withServerSsh(host, (conn) => sendRcon(conn, row.containerName, user.id, parsed.command));
297	    if (!result.ok) return { error: result.error || "Server is asleep — connect first to wake it up." };
298	    return { response: result.response };
299	  } catch (e) {
300	    console.error("[free-minecraft] rcon command failed:", e);
301	    return { error: "Couldn't reach your server — is it asleep? Connect first to wake it up." };
302	  }
303	}
304	
305	export async function getFreeMinecraftPlayers() {
306	  const user = await requireUser();
307	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
308	  if (!row) return { ok: false as const, error: "You don't have a free server." };
309	
310	  try {
311	    const host = await freemcHost();
312	    return await withServerSsh(host, (conn) => getFreeServerPlayers(conn, row.containerName, user.id));
313	  } catch {
314	    return { ok: false as const, error: "Server is asleep." };
315	  }
316	}
317	
318	/** Current server.properties values, shaped for the shared MINECRAFT schema
319	 *  (lib/game-config.ts) — same field defs/types/options the paid game panel's
320	 *  Settings tab uses, just applied through Docker instead of a VM job. */
321	export async function getFreeMinecraftSettings() {
322	  const user = await requireUser();
323	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
324	  if (!row) return null;
325	
326	  const schema = schemaFor("minecraft");
327	  if (!schema) return null;
328	
329	  try {
330	    const host = await freemcHost();
331	    const properties = await withServerSsh(host, (conn) => readServerProperties(conn, row.containerName));
332	    return { schema, properties };
333	  } catch {
334	    return { schema, properties: {} };
335	  }
336	}
337	
338	export async function applyFreeMinecraftSettings(_prev: unknown, formData: FormData): Promise<Result> {
339	  const user = await requireUser();
340	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
341	  if (!row) return { error: "You don't have a free server." };
342	
343	  const schema = schemaFor("minecraft");
344	  if (!schema) return { error: "Settings aren't available." };
345	
346	  const raw: Record<string, unknown> = {};
347	  for (const field of schema.fields) {
348	    const v = formData.get(field.key);
349	    if (v === null) continue;
350	    raw[field.key] = field.type === "bool" ? v === "true" : v;
351	  }
352	  const validated = validateConfig("minecraft", raw);
353	  if (!validated.ok) return { error: validated.error };
354	
355	  const properties: Record<string, string> = {};
356	  for (const [k, v] of Object.entries(validated.values)) properties[k] = String(v);
357	
358	  try {
359	    const host = await freemcHost();
360	    await withServerSsh(host, async (conn) => {
361	      // Push live-appliable keys immediately via RCON (instant effect for
362	      // anyone already connected), THEN write server.properties + restart so
363	      // the change also survives the restart and applies to everyone else —
364	      // see liveRconCommandFor's own note on which keys have a real live path.
365	      for (const [k, v] of Object.entries(properties)) {
366	        const liveCmd = liveRconCommandFor(k, v);
367	        if (liveCmd) await sendRcon(conn, row.containerName, user.id, liveCmd).catch(() => {});
368	      }
369	      const write = await writeServerProperties(conn, row.containerName, properties);
370	      if (!write.ok) throw new Error(write.error || "Could not write settings.");
371	      await exec(conn, `docker restart ${shellQuote(row.containerName)}`, 30_000);
372	    });
373	  } catch (e) {
374	    console.error("[free-minecraft] settings apply failed:", e);
375	    return { error: "Couldn't apply settings — please try again." };
376	  }
377	  await db.freeMinecraftServer.update({ where: { id: row.id }, data: { preset: "custom" } });
378	  revalidatePath("/dashboard/free-minecraft");
379	  return {};
380	}
381	
382	export async function applyFreeMinecraftPreset(_prev: unknown, formData: FormData): Promise<Result> {
383	  const user = await requireUser();
384	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
385	  if (!row) return { error: "You don't have a free server." };
386	
387	  const presetKey = String(formData.get("preset") ?? "");
388	  const preset = FREEMC_PRESETS[presetKey];
389	  if (!preset) return { error: "Unknown preset." };
390	
391	  const rl = checkRateLimit(`freemc:preset:${user.id}`, { max: 10, windowMs: 60_000 });
392	  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };
393	
394	  try {
395	    const host = await freemcHost();
396	
397	    if (preset.kind === "properties") {
398	      // Same container, same install — just server.properties + restart.
399	      await withServerSsh(host, async (conn) => {
400	        for (const [k, v] of Object.entries(preset.properties)) {
401	          const liveCmd = liveRconCommandFor(k, v);
402	          if (liveCmd) await sendRcon(conn, row.containerName, user.id, liveCmd).catch(() => {});
403	        }
404	        // Switching to a properties-only preset (e.g. back to Vanilla) also
405	        // clears any plugins a PREVIOUS plugins-based preset left installed —
406	        // otherwise an old SkyBlock/Prison/etc. jar would keep running against
407	        // a "vanilla" world it was never meant for.
408	        await exec(conn, `docker exec ${shellQuote(row.containerName)} sh -c 'rm -rf /data/plugins/*'`, 15_000).catch(() => {});
409	        const write = await writeServerProperties(conn, row.containerName, preset.properties);
410	        if (!write.ok) throw new Error(write.error || "Could not write settings.");
411	        await exec(conn, `docker restart ${shellQuote(row.containerName)}`, 30_000);
412	      });
413	    } else {
414	      // Plugin-based preset: MODRINTH_PROJECTS/SPIGET_RESOURCES/TYPE are only
415	      // read at container-creation time, so this recreates the container —
416	      // same data volume (world untouched), same container name, new image
417	      // config. Clearing /data/plugins first means switching FROM one
418	      // plugins-based preset to another never leaves the old preset's jars
419	      // behind to conflict with the new one.
420	      //
421	      // `docker run -d` returns the instant the container STARTS, not once
422	      // its entrypoint actually succeeds — a bad plugin download or a
423	      // version-availability mismatch (a real one hit in testing: a plugin
424	      // with no published build for the newest MC release yet) kills the
425	      // container seconds into its own init, well after `docker run` already
426	      // reported success. So this ALWAYS verifies the container is still
427	      // running a few seconds later, and if the new preset's install turns
428	      // out broken, it rolls back to the account's PREVIOUS preset rather
429	      // than leaving the customer with a dead container — better a stale
430	      // preset than no server at all.
431	      const domain = await getSetting("free_minecraft_domain", "play.nxeon.cloud");
432	      const ramMb = await getSettingInt("free_minecraft_ram_mb", 1024);
433	      const previous = FREEMC_PRESETS[row.preset] ?? FREEMC_PRESETS.vanilla;
434	
435	      const outcome = await withServerSsh(host, async (conn) => {
436	        await exec(conn, `docker exec ${shellQuote(row.containerName)} sh -c 'rm -rf /data/plugins/*'`, 15_000).catch(() => {});
437	        const applied = await recreatePresetContainer(conn, row, preset, user.id, domain, ramMb);
438	        if (applied.ok) return { ok: true as const };
439	
440	        console.error("[free-minecraft] preset boot failed, rolling back:", applied.error);
441	        const rolledBack = await recreatePresetContainer(conn, row, previous, user.id, domain, ramMb);
442	        return rolledBack.ok
443	          ? { ok: false as const, error: "That preset didn't start cleanly, so we put your server back the way it was." }
444	          : { ok: false as const, error: "That preset didn't start, and restoring your previous setup also failed — please contact support." };
445	      });
446	      if (!outcome.ok) return { error: outcome.error };
447	    }
448	  } catch (e) {
449	    console.error("[free-minecraft] preset apply failed:", e);
450	    return { error: "Couldn't apply that preset — please try again." };
451	  }
452	  await db.freeMinecraftServer.update({ where: { id: row.id }, data: { preset: presetKey } });
453	  revalidatePath("/dashboard/free-minecraft");
454	  return {};
455	}
456	
457	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
458	
459	/** Recreates the free server's container for `preset` and verifies it's
460	 *  still alive ~15s later (long enough for an init-time plugin/version
461	 *  failure to have already killed it — a normal boot takes 60s+ and would
462	 *  never trip this). Never throws; the caller decides what a failure means. */
463	async function recreatePresetContainer(
464	  conn: import("ssh2").Client,
465	  row: { id: string; containerName: string; subdomain: string },
466	  preset: (typeof FREEMC_PRESETS)[string],
467	  userId: string,
468	  domain: string,
469	  ramMb: number,
470	): Promise<{ ok: boolean; error?: string }> {
471	  const jvmRatio = preset.kind === "plugins" ? 0.7 : 0.85; // plugins need more non-heap headroom (Netty, plugin state, extra dimensions) — an 85% split OOM-killed a real plugin preset in testing
472	  const jvmMb = Math.max(256, Math.round(ramMb * jvmRatio));
473	  const envVars = preset.kind === "plugins" ? { ...propertiesToEnv(preset.properties), ...(preset.env ?? {}) } : {};
474	  const envFlags = Object.entries(envVars)
475	    .map(([k, v]) => `-e ${k}=${shellQuote(v)}`)
476	    .join(" ");
477	
478	  await exec(conn, `docker rm -f ${shellQuote(row.containerName)}`, 30_000);
479	  const cmd = [
480	    "docker run -d",
481	    `--name ${shellQuote(row.containerName)}`,
482	    "--network freemc",
483	    `--memory=${ramMb}m --memory-swap=${ramMb}m --cpus=1`,
484	    `--label mc-router.host=${shellQuote(`${row.subdomain}.${domain}`)}`,
485	    `-v ${shellQuote(`/opt/freemc/servers/${row.id}`)}:/data`,
486	    `-e EULA=TRUE -e TYPE=${preset.type ?? "VANILLA"} -e ONLINE_MODE=FALSE`,
487	    preset.kind === "plugins" ? `-e VERSION=${shellQuote(FREEMC_PLUGIN_MC_VERSION)}` : "",
488	    `-e MEMORY=${jvmMb}m`,
489	    `-e ENABLE_RCON=true -e RCON_PASSWORD=${shellQuote(rconPasswordFor(userId))}`,
490	    envFlags,
491	    "itzg/minecraft-server",
492	  ].join(" ");
493	  const run = await exec(conn, cmd, 90_000); // plugin downloads can take longer than a plain boot
494	  if (run.code !== 0) return { ok: false, error: run.stderr || "docker run failed" };
495	
496	  await sleep(15_000);
497	  const check = await exec(conn, `docker inspect -f '{{.State.Running}}' ${shellQuote(row.containerName)}`, 10_000);
498	  if (check.code !== 0 || check.stdout.trim() !== "true") {
499	    return { ok: false, error: "Container exited shortly after starting." };
500	  }
501	  return { ok: true };
502	}
