"use server";

/**
 * Opt-in public listing controls for a free Minecraft server — purely a DB
 * update gating what's shown on the public directory (/servers) and the
 * server's own shareable page (/servers/[subdomain]). Never touches the
 * container, SSH, or mc-router: making a server "public" only changes whether
 * its address/description is exposed on those pages, not how it's reached —
 * the server was already joinable at its subdomain the moment it existed.
 *
 * Sibling to lib/actions-free-minecraft.ts, kept in its own file so the
 * directory feature can be reviewed/shipped independently of the core
 * create/power/settings actions.
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { checkRateLimit } from "./rate-limit";

type Result = { error?: string; ok?: boolean };

const TAGLINE_MAX = 80;
const DESCRIPTION_MAX = 600;

export async function updateFreeMinecraftPublicListing(_prev: unknown, formData: FormData): Promise<Result> {
  const user = await requireUser();
  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  if (!row) return { error: "You don't have a free server." };

  const rl = checkRateLimit(`freemc:public-listing:${user.id}`, { max: 10, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };

  const isPublic = formData.get("isPublic") === "on" || formData.get("isPublic") === "true";
  // Rendered as plain text (never dangerouslySetInnerHTML) on the public pages,
  // so no HTML sanitization is needed here — just trim whitespace and cap
  // length so a listing can't blow out the directory/card layout.
  const publicTagline = String(formData.get("publicTagline") ?? "").trim().slice(0, TAGLINE_MAX);
  const publicDescription = String(formData.get("publicDescription") ?? "").trim().slice(0, DESCRIPTION_MAX);

  await db.freeMinecraftServer.update({
    where: { id: row.id },
    data: {
      isPublic,
      publicTagline: publicTagline || null,
      publicDescription: publicDescription || null,
    },
  });

  revalidatePath("/dashboard/free-minecraft");
  revalidatePath("/servers");
  revalidatePath(`/servers/${row.subdomain}`);
  return { ok: true };
}

"use client";

/**
 * Opt-in public directory listing controls for a free Minecraft server —
 * matches the card style of the existing Manage tab (see the `Manage`
 * component in FreeMcDashboard.tsx: `card max-w-md space-y-3`, same
 * input/btn-secondary treatment) so it drops in cleanly as another card in
 * that tab. Deliberately NOT wired into FreeMcDashboard.tsx here — that's a
 * follow-up integration step; this component is self-contained and only
 * needs the server row passed in as a prop.
 */
import { useActionState } from "react";
import Link from "next/link";
import { updateFreeMinecraftPublicListing } from "@/lib/actions-freemc-public";

const TAGLINE_MAX = 80;
const DESCRIPTION_MAX = 600;

type Server = {
  subdomain: string;
  isPublic: boolean;
  publicTagline: string | null;
  publicDescription: string | null;
};

export function PublicListingCard({ server }: { server: Server }) {
  const [state, action, pending] = useActionState(updateFreeMinecraftPublicListing, {});

  return (
    <form action={action} className="card max-w-md space-y-3">
      <h3 className="font-semibold text-[var(--fg)]">Public directory listing</h3>
      <p className="text-xs text-slate-500">
        List your server on the Nxeon public directory so anyone can find it and join — off by default. Your
        connect address is only shown publicly while this is on.
      </p>

      {state.error && <p className="text-sm text-red-400">{state.error}</p>}
      {state.ok && <p className="text-sm text-emerald-400">Saved.</p>}

      <label className="flex items-center gap-2.5 text-sm text-[var(--fg)]">
        <input
          type="checkbox"
          name="isPublic"
          defaultChecked={server.isPublic}
          className="h-4 w-4 rounded border-white/20 bg-transparent"
        />
        List this server publicly
      </label>

      <div>
        <label className="label">Tagline</label>
        <input
          className="input"
          name="publicTagline"
          defaultValue={server.publicTagline ?? ""}
          maxLength={TAGLINE_MAX}
          placeholder="A friendly survival world for new players"
        />
        <p className="mt-1 text-xs text-slate-500">Shown on your directory card — up to {TAGLINE_MAX} characters.</p>
      </div>

      <div>
        <label className="label">Description</label>
        <textarea
          className="input min-h-[100px] resize-y"
          name="publicDescription"
          defaultValue={server.publicDescription ?? ""}
          maxLength={DESCRIPTION_MAX}
          placeholder="Tell visitors what to expect — rules, community, how long the world's been running..."
        />
        <p className="mt-1 text-xs text-slate-500">
          Shown on your server's own page — up to {DESCRIPTION_MAX} characters.
        </p>
      </div>

      <button className="btn-secondary text-sm" disabled={pending}>
        {pending ? "Saving…" : "Save listing"}
      </button>

      {server.isPublic && (
        <p className="text-xs text-slate-500">
          <Link href={`/servers/${server.subdomain}`} className="text-brand-300 hover:text-brand-200">
            View your public page →
          </Link>
        </p>
      )}
    </form>
  );
}

