    images: [OG_IMAGE],
  },
};

// No pagination in v1 — capped at a sane page size and newest-first so the
// directory can never grow unbounded or slow. Once listings meaningfully
// exceed this, add real pagination rather than raising the cap indefinitely.
const DIRECTORY_CAP = 48;

export const dynamic = "force-dynamic";

export default async function ServersDirectoryPage() {
  const domain = await getSetting("free_minecraft_domain", "play.nxeon.cloud");

  // Deliberately no live player-count lookups here: that would mean an SSH
  // round trip to freemc-host per listed server (up to DIRECTORY_CAP of them)
  // on every render of a public, unauthenticated page — a slow or briefly
  // unreachable host would take the whole directory down with it. Live status
  // is shown on each server's own page (/servers/[subdomain]) instead, where
  // it's a single lookup.
  const servers = await db.freeMinecraftServer.findMany({
    where: { isPublic: true, status: "READY" },
    orderBy: { createdAt: "desc" },
    take: DIRECTORY_CAP,
    select: {
      subdomain: true,
      name: true,
      preset: true,
      publicTagline: true,
      createdAt: true,
    },
  });

  return (
    <div className="relative min-h-screen overflow-hidden">
      <div aria-hidden className="pointer-events-none absolute inset-0 z-0">
        <AmbientField />
        <div className="absolute inset-0 bg-[radial-gradient(ellipse_70%_50%_at_15%_-5%,rgba(111,71,245,0.14),transparent_60%),radial-gradient(ellipse_60%_45%_at_95%_0%,rgba(59,130,246,0.10),transparent_60%)]" />
      </div>

      <div className="relative z-10">
        <GameHero
          family="minecraft"
          eyebrow="Public directory"
          title="Public Minecraft servers."
          highlight="Pick one, connect now."
          sub={
            <>
              Every server below is a real free Nxeon server whose owner opted in to be listed. No account needed
              to join — copy the address and connect. Want your own?{" "}
              <Link href="/free-minecraft" className="text-brand-300 underline underline-offset-2 hover:text-brand-200">
                Get a free server
              </Link>{" "}
              and list it here too.
            </>
          }
          primary={{ label: "Create my free server", href: "/dashboard/free-minecraft" }}
          secondary={{ label: "Need more power? See paid servers", href: "/game-servers" }}
        />

        <Section>
          <SectionTitle
            eyebrow={`${servers.length} listed`}
            title="Browse the directory"
            sub="Owner-submitted taglines and game modes — nothing here is curated or ranked, just newest first."
            align="left"
          />

          {servers.length === 0 ? (
            <div className="card mt-10 text-center">
              <p className="text-sm text-slate-400">
                No public servers yet — be the first.{" "}
                <Link href="/dashboard/free-minecraft" className="text-brand-300 hover:text-brand-200">
                  Create a free server
                </Link>{" "}
                and turn on public listing from its Manage tab.
              </p>
            </div>
          ) : (
            <div className="mt-10 grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
              {servers.map((s, i) => {
                const preset = FREEMC_PRESETS[s.preset] ?? FREEMC_PRESETS.vanilla;
                const displayName = s.name || s.subdomain;
                const address = `${s.subdomain}.${domain}`;
                return (
                  <Reveal key={s.subdomain} delay={Math.min(i, 8) * 40} className="card flex flex-col gap-3">
                    <div className="flex items-center gap-3">
                      <GameLogo family="minecraft" size={36} />
                      <div className="min-w-0">
                        <h3 className="truncate font-semibold text-[var(--fg)]">{displayName}</h3>
                        <span className="text-xs text-brand-300">{preset.label}</span>
                      </div>
                    </div>
                    {s.publicTagline && (
                      <p className="text-sm text-[var(--fg-muted)] line-clamp-2">{s.publicTagline}</p>
                    )}
                    <p className="text-xs text-slate-500 line-clamp-2">{preset.description}</p>
                    <code className="truncate rounded-lg border border-white/[0.08] bg-black/20 px-2.5 py-1.5 text-xs text-slate-300">
                      {address}
                    </code>
                    <Link
                      href={`/servers/${s.subdomain}`}
                      className="mt-auto inline-flex items-center gap-1.5 text-sm font-semibold text-brand-300 hover:text-brand-200"
                    >
                      View server →
                    </Link>
                  </Reveal>
                );
              })}
            </div>
          )}
        </Section>

        <CtaBand
          title="Get your own free Minecraft server"
          sub="No credit card, live in under a minute, and you can list it here the moment it's ready."
          primary={{ label: "Create my free server", href: "/dashboard/free-minecraft" }}
          secondary={{ label: "Learn how it works", href: "/free-minecraft" }}
        />
      </div>
    </div>
  );
}

