"use client";

/**
 * Small copy-to-clipboard affordance for a server's connect address, used on
 * its public page (app/(marketing)/servers/[subdomain]/page.tsx). Split into
 * its own client component because the page itself is a server component
 * (it needs generateMetadata + notFound()), and "use client" can't be mixed
 * into that file — same navigator.clipboard pattern FreeMcDashboard.tsx uses.
 */
import { useState } from "react";

export function ConnectAddressCopy({ address }: { address: string }) {
  const [copied, setCopied] = useState(false);

  async function copy() {
    try {
      await navigator.clipboard.writeText(address);
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    } catch {
      /* clipboard API unavailable — silently no-op, the address is still selectable text */
    }
  }

  return (
    <div className="flex items-center gap-2">
      <code className="rounded-lg border border-white/[0.08] bg-black/20 px-3 py-2 text-sm text-slate-200">{address}</code>
      <button type="button" className="btn-ghost text-xs" onClick={copy}>
        {copied ? "Copied!" : "Copy"}
      </button>
    </div>
  );
}

import Link from "next/link";
import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { getSetting } from "@/lib/settings";
import { FREEMC_PRESETS, getFreeServerStatus } from "@/lib/free-minecraft-control";
import { withServerSsh } from "@/lib/ssh-exec";
import { AmbientField } from "@/components/marketing/AmbientField";
import { Section } from "@/components/marketing/primitives";
import { CtaBand } from "@/components/marketing/sections";
import { GameLogo } from "@/components/marketing/GameLogo";
import { ConnectAddressCopy } from "@/components/customer/freemc/ConnectAddressCopy";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";
const OG_IMAGE = `${APP_URL}/games/art/minecraft_hero.jpg`;

// Always render fresh: this route's whole security model is "a server that
// isn't public right now must 404 right now" — see the notFound() gate below.
// Caching a "found" render would risk serving a stale page for a server the
// owner just made private again.
export const dynamic = "force-dynamic";

type Params = { params: Promise<{ subdomain: string }> };

/** Loads the row and applies the exact same public/ready gate the page itself
 *  uses, so metadata generation and the page body can never disagree about
 *  whether this server is visible. */
async function loadPublicServer(subdomain: string) {
  const row = await db.freeMinecraftServer.findUnique({
    where: { subdomain },
    select: {
      subdomain: true,
      name: true,
      preset: true,
      status: true,
      isPublic: true,
      publicTagline: true,
      publicDescription: true,
      containerName: true,
    },
  });
  if (!row || !row.isPublic || row.status !== "READY") return null;
  return row;
}

export async function generateMetadata({ params }: Params): Promise<Metadata> {
  const { subdomain } = await params;
  const server = await loadPublicServer(subdomain);
  if (!server) return { title: "Server not found" };

  const domain = await getSetting("free_minecraft_domain", "play.nxeon.cloud");
  const preset = FREEMC_PRESETS[server.preset] ?? FREEMC_PRESETS.vanilla;
  const displayName = server.name || server.subdomain;
  const title = `${displayName} — ${preset.label} Minecraft Server | Nxeon`;
  const description =
    server.publicTagline ||
    `Join ${displayName}, a free ${preset.label} Minecraft server at ${server.subdomain}.${domain} — hosted free on Nxeon.`;

  return {
    title,
    description,
    alternates: { canonical: `/servers/${server.subdomain}` },
    openGraph: {
      type: "website",
      title,
      description,
      url: `${APP_URL}/servers/${server.subdomain}`,
      images: [{ url: OG_IMAGE, width: 1200, height: 630, alt: `${displayName} — Minecraft server` }],
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      images: [OG_IMAGE],
    },
  };
}

/** Best-effort live status, bounded to a few seconds regardless of what
 *  freemc-host is doing — a public marketing page must never hang or fail
 *  because of it. Returns null (rendered as "status unknown") on any timeout,
 *  SSH error, or if the host row itself is missing. */
async function getLiveStatusBestEffort(containerName: string): Promise<{ running: boolean; players: { online: number; max: number } | null } | null> {
  const withTimeout = <T,>(p: Promise<T>, ms: number): Promise<T> =>
    new Promise((resolve, reject) => {
      const t = setTimeout(() => reject(new Error("timeout")), ms);
      p.then((v) => { clearTimeout(t); resolve(v); }, (e) => { clearTimeout(t); reject(e); });
    });

  try {
    const host = await db.server.findFirst({
      where: { hostname: "freemc-host" },
      select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
    });
    if (!host) return null;
    return await withTimeout(
      withServerSsh(host, (conn) => getFreeServerStatus(conn, containerName)),
      4_000,
    );
  } catch {
    return null;
  }
}

export default async function PublicServerPage({ params }: Params) {
  const { subdomain } = await params;
  const server = await loadPublicServer(subdomain);
  // Hard privacy gate: a private, missing, or not-yet-ready server must be
  // indistinguishable from a URL that was never valid — plain 404, nothing
  // more specific in the response.
  if (!server) notFound();

  const [domain, live] = await Promise.all([
    getSetting("free_minecraft_domain", "play.nxeon.cloud"),
    getLiveStatusBestEffort(server.containerName),
  ]);

  const preset = FREEMC_PRESETS[server.preset] ?? FREEMC_PRESETS.vanilla;
  const displayName = server.name || server.subdomain;
  const address = `${server.subdomain}.${domain}`;

  return (
    <div className="relative min-h-screen overflow-hidden">
      <div aria-hidden className="pointer-events-none absolute inset-0 z-0">
        <AmbientField />
        <div className="absolute inset-0 bg-[radial-gradient(ellipse_70%_50%_at_15%_-5%,rgba(111,71,245,0.14),transparent_60%),radial-gradient(ellipse_60%_45%_at_95%_0%,rgba(59,130,246,0.10),transparent_60%)]" />
      </div>

      <div className="relative z-10">
        <Section size="lg">
          <div className="mx-auto max-w-2xl text-center">
            <div className="mb-3 text-xs">
              <Link href="/servers" className="text-slate-400 transition-colors hover:text-white">
                ← Back to the directory
              </Link>
            </div>
            <div className="mx-auto mb-5 w-16">
              <GameLogo family="minecraft" size={64} />
            </div>
            <h1 className="text-3xl font-bold tracking-tight text-[var(--fg)] sm:text-4xl text-balance">{displayName}</h1>
            <p className="mt-2 text-sm font-medium text-brand-300">{preset.label}</p>
            {server.publicTagline && (
              <p className="mt-4 text-lg leading-relaxed text-[var(--fg-muted)]">{server.publicTagline}</p>
            )}

            {live && (
              <div className="mt-5 inline-flex items-center gap-2 rounded-full border border-white/[0.08] bg-black/20 px-3 py-1.5 text-xs text-slate-300">
                <span className={`h-2 w-2 rounded-full ${live.running ? "bg-emerald-400" : "bg-slate-500"}`} />
                {live.running
                  ? `Awake — ${live.players?.online ?? 0} / ${live.players?.max ?? "?"} online`
                  : "Asleep — connecting will wake it up"}
              </div>
            )}

            <div className="mt-6 flex justify-center">
              <ConnectAddressCopy address={address} />
            </div>
          </div>
        </Section>

        <Section tone="panel">
          <div className="mx-auto grid max-w-3xl gap-6 sm:grid-cols-2">
            <div className="card">
              <h2 className="font-semibold text-[var(--fg)]">About this server</h2>
              <p className="mt-2 text-sm leading-relaxed text-[var(--fg-muted)] whitespace-pre-wrap">
                {server.publicDescription || "The owner hasn't added a description yet."}
              </p>
            </div>
            <div className="card">
              <h2 className="font-semibold text-[var(--fg)]">Game mode — {preset.label}</h2>
              <p className="mt-2 text-sm leading-relaxed text-[var(--fg-muted)]">{preset.description}</p>
              {preset.setupNote && <p className="mt-2 text-xs text-amber-300/80">{preset.setupNote}</p>}
            </div>
          </div>
        </Section>

        <CtaBand
          title="Want your own free Minecraft server?"
          sub="No credit card, live in under a minute — list it in the directory the moment it's ready."
          primary={{ label: "Create my free server", href: "/dashboard/free-minecraft" }}
          secondary={{ label: "Browse more servers", href: "/servers" }}
        />
      </div>
    </div>
  );
}

